/*
 * Agilent E13125A Scope Sweeper
 * Automatically sweep signal using trigger configuration via software control
 */

#include <stdio.h>
#include <stdlib.h>

#define FREQUENCY_RANGE 2000

int main(int argc, char **argv) {
    int frequency;
    unsigned long long sourceFreq[10];
    char filename[100];

    // Input parameters
    printf("Enter the frequency to start sweeping from:\n");
    scanf("%d", &frequency);

    // Buffer size
    size_t bufferSize = sizeof(sourceFreq);

    // Generate frequency list
    for(size_t i=0; i < 10; ++i) {
        sourceFreq[i] = frequency + (i * FREQUENCY_RANGE);
    }

    // Save data to file
    sprintf(filename, "scope_sweep_%d.txt", frequency);
    FILE *file = fopen(filename, "w+");
    if (!file) {
        fprintf(stderr, "Failed to open file.\n");
        return 1;
    }

    // Write header
    fprintf(file, "Frequency\tReading\n");

    // Sweep loop
    for(int i=0; i < 10; ++i) {
        // Wait for internal SCPI trigger to activate
        system("sleep 0.01");

        // Read sample
        for(size_t j=0; j < bufferSize; ++j) {
            double val = read_sample();
            fprintf(file, "%g\t%.3f\n", sourceFreq[i], val);
        }
    }

    fclose(file);
    return 0;
}

double read_sample(void) {
    // Dummy function to simulate analog reading
    static volatile double sample = 0.0;
    static bool first = true;

    if(first) {
        sample = (double)(rand()) / RAND_MAX; // Random value between 0 and 1
        first = false;
    } else {
        sample += ((double)rand()) / RAND_MAX);
    }

    return sample;
}

