        const slides = document.querySelectorAll(".slide");
        const slideWidth = window.innerWidth / 3; // One per row

        if (x > 0 && x < slideWidth * 2) {
            const rowIndex = Math.floor(x / slideWidth);
            const slideIndex = rowIndex * 2 + currentSlide;
            if (slideIndex >= slides.length) return;
            slides[slideIndex].style.transform = `translateX(${x}px)`;;
        } else {
            slides[currentSlide].style.transform = `translateX(0px)`;
        }
    });

    document.getElementById("playlist").addEventListener("mouseup", (e) => {
        document.getElementById("playlist").style.cursor = 'default';
    });
});

